From ae943325a8a4fd79eb6c8c9d7309045c4d911f7b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:04:19 +0100
Subject: [PATCH] kde-open: open help URLs on docs.kde.org without a help
 viewer

Without KHelpCenter nothing handles help:/ URLs, so kde-open failed on
them with a "file not found" error. Now it opens the same page of the
online documentation, in the user's language, when no viewer is around.

BUG: 509464
---
 kioclient/kioclient.cpp | 37 +++++++++++++++++++++++++++++++++++++
 1 file changed, 37 insertions(+)

diff --git a/kioclient/kioclient.cpp b/kioclient/kioclient.cpp
index 6d94d2fa..558891a4 100644
--- a/kioclient/kioclient.cpp
+++ b/kioclient/kioclient.cpp
@@ -10,6 +10,7 @@

 #include <KIO/CopyJob>
 #include <KIO/DeleteJob>
+#include <KIO/DesktopExecParser>
 #include <KIO/MkdirJob>
 #include <kio/listjob.h>
 #include <kio/transferjob.h>
@@ -29,6 +30,7 @@
 #include <QDBusConnection>
 #include <QDebug>
 #include <QFileDialog>
+#include <QLocale>
 #include <QUrlQuery>
 #include <iostream>

@@ -240,6 +242,37 @@ static void checkArgumentCount(int count, int min, int max)
 }

 #ifndef KIOCORE_ONLY
+// Maps help:/<application>/<page> to the same page on docs.kde.org, for systems without a help viewer
+static QUrl onlineHelpUrl(const QUrl &helpUrl)
+{
+    QString application = helpUrl.path();
+    if (application.startsWith(QLatin1Char('/'))) {
+        application.remove(0, 1);
+    }
+    QString page = QStringLiteral("index.html");
+    if (application.endsWith(QLatin1String(".html"))) {
+        const int slash = application.lastIndexOf(QLatin1Char('/'));
+        page = application.mid(slash + 1);
+        application.truncate(std::max(slash, 0));
+    }
+    if (application.endsWith(QLatin1Char('/'))) {
+        application.chop(1);
+    }
+
+    QUrl url(QStringLiteral("https://docs.kde.org/"));
+    if (!application.isEmpty()) {
+        url.setPath(QStringLiteral("/index.php"));
+        QUrlQuery query;
+        query.addQueryItem(QStringLiteral("branch"), QStringLiteral("stable5"));
+        query.addQueryItem(QStringLiteral("language"), QLocale().name());
+        query.addQueryItem(QStringLiteral("application"), application);
+        query.addQueryItem(QStringLiteral("path"), page);
+        url.setQuery(query);
+        url.setFragment(helpUrl.fragment());
+    }
+    return url;
+}
+
 bool ClientApp::kde_open(const QString &_url, const QString &mimeType, bool allowExec)
 {
     QString url = _url;
@@ -259,6 +292,10 @@ bool ClientApp::kde_open(const QString &_url, const QString &mimeType, bool allo
         info.url.setQuery(q);
     }

+    if (info.url.scheme() == QLatin1String("help") && !KIO::DesktopExecParser::hasSchemeHandler(info.url)) {
+        info.url = onlineHelpUrl(info.url);
+    }
+
     auto *job = new KIO::OpenUrlJob(info.url, mimeType);
     job->setUiDelegate(KIO::createDefaultJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled, nullptr));
     job->setRunExecutables(allowExec);
